import { useCallback, useEffect, useRef, useState } from 'react'
import type { FormEvent, ReactNode } from 'react'
import { ArrowDownRight, ArrowRight, ArrowUpRight, BarChart3, Bell, Check, ChevronDown, ChevronRight, Heart, Home, Info, LayoutGrid, LoaderCircle, MapPin, Minus, Moon, Plus, ScanLine, Search, Settings2, ShieldCheck, ShoppingBag, ShoppingCart, SlidersHorizontal, Sparkles, Sun, Trash2, TrendingDown, UserRound, X, Camera, Globe, AlertCircle, ExternalLink, RefreshCw, Send, GitCompareArrows } from 'lucide-react'
import { api, money } from './api'
import Artwork from './Artwork'
import type { Alert, BasketResult, CartEntry, Category, Detail, Product, Store, Offer } from './types'

type Page='catalog'|'basket'|'favorites'|'alerts'|'assistant'|'scan'|'profile'|'compare'|'history'|'admin'
type Lang='uz'|'ru'
type Profile={region:string;language:Lang;notifications_enabled:boolean;regions:{id:string;name:string}[]}
const defaultRegions=[['tashkent','Toshkent shahri'],['tashkent-region','Toshkent viloyati'],['andijan','Andijon'],['bukhara','Buxoro'],['fergana','Farg‘ona'],['jizzakh','Jizzax'],['khorezm','Xorazm'],['namangan','Namangan'],['navoiy','Navoiy'],['kashkadarya','Qashqadaryo'],['karakalpakstan','Qoraqalpog‘iston'],['samarkand','Samarqand'],['sirdarya','Sirdaryo'],['surkhandarya','Surxondaryo']]
const dictionary:Record<string,[string,string]>={catalog:['Katalog','Каталог'],basket:['Savatcha','Корзина'],favorites:['Sevimlilar','Избранное'],alerts:['Kuzatuvlar','Отслеживание'],assistant:['Xarid maslahatchisi','Советник по покупкам'],scan:['Shtrix-kod skaneri','Сканер штрихкода'],profile:['Profil va sozlamalar','Профиль и настройки'],compare:['Solishtirish','Сравнение'],history:['Narxlar tarixi','История цен'],admin:['Boshqaruv','Управление'],search:['Mahsulot, model yoki brend qidiring…','Товар, модель или бренд…'],all:['Barchasi','Все'],popular:['Siz uchun tanladik','Товары для вас'],cheap:['Eng arzon','Дешевле'],expensive:['Eng qimmat','Дороже'],discount:['Eng ko‘p arzonlashgan','Больше скидка'],newest:['Yangi qo‘shilgan','Новинки'],add:['Savatchaga','В корзину'],details:['Batafsil','Подробнее'],shops:['do‘konda','магазинов'],empty:['Hozircha hech narsa yo‘q','Пока ничего нет'],clear:['Tozalash','Очистить'],close:['Yopish','Закрыть'],apply:['Qo‘llash','Применить'],delivery:['Yetkazish','Доставка'],total:['Jami','Итого'],quantity:['Soni','Количество'],loading:['Yuklanmoqda…','Загрузка…'],retry:['Qayta urinish','Повторить'],demo:['Demo ma’lumotlar','Демонстрационные данные']}
const readCart=():CartEntry[]=>{try{const data=JSON.parse(localStorage.getItem('ea-cart')||'[]');return Array.isArray(data)?data.filter(x=>x?.product?.id && Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=20).slice(0,8):[]}catch{return []}}
const validPage=(s:string|null):s is Page=>['catalog','basket','favorites','alerts','assistant','scan','profile','compare','history','admin'].includes(s||'')

export default function App(){
 const searchParams=new URLSearchParams(window.location.search)
 const [page,setPage]=useState<Page>(validPage(searchParams.get('view'))?searchParams.get('view') as Page:'catalog')
 const [lang,setLang]=useState<Lang>(localStorage.getItem('ea-lang')==='ru'?'ru':'uz')
 const [dark,setDark]=useState(localStorage.getItem('ea-dark')==='true'||(localStorage.getItem('ea-dark')===null&&window.Telegram?.WebApp.colorScheme==='dark'))
 const [region,setRegion]=useState(localStorage.getItem('ea-region')||'tashkent')
 const [regions,setRegions]=useState(defaultRegions),[profileReady,setProfileReady]=useState(false),[demoMode,setDemoMode]=useState(true)
 const [notifications,setNotifications]=useState(true),[settingsSaving,setSettingsSaving]=useState(false),[confirmDelete,setConfirmDelete]=useState(false),[deleting,setDeleting]=useState(false)
 const [products,setProducts]=useState<Product[]>([]), [categories,setCategories]=useState<Category[]>([]),[stores,setStores]=useState<Store[]>([])
 const [favorites,setFavorites]=useState<Product[]>([]),[alerts,setAlerts]=useState<Alert[]>([])
 const [cart,setCart]=useState<CartEntry[]>(readCart),[compared,setCompared]=useState<Product[]>([])
 const [query,setQuery]=useState(''),[debounced,setDebounced]=useState(''),[category,setCategory]=useState(''),[sort,setSort]=useState('price_asc')
 const [minPrice,setMinPrice]=useState(''),[maxPrice,setMaxPrice]=useState(''),[store,setStore]=useState(''),[filters,setFilters]=useState(false)
 const [loading,setLoading]=useState(true),[error,setError]=useState(''),[total,setTotal]=useState(0),[listPage,setListPage]=useState(1),[refresh,setRefresh]=useState(0)
 const [selected,setSelected]=useState<Detail|null>(null),[detailLoading,setDetailLoading]=useState(false),[toast,setToast]=useState(''),[target,setTarget]=useState(''),[alertBusy,setAlertBusy]=useState(false)
 const [basket,setBasket]=useState<BasketResult|null>(null),[basketBusy,setBasketBusy]=useState(false)
 const [message,setMessage]=useState(''),[answer,setAnswer]=useState<{answer:string;products:Product[];mode:string}|null>(null),[assistantBusy,setAssistantBusy]=useState(false)
 const [barcode,setBarcode]=useState(''),[localPrice,setLocalPrice]=useState(''),[scanResult,setScanResult]=useState<Detail|null>(null),[scanBusy,setScanBusy]=useState(false)
 const [camera,setCamera]=useState(false),[cameraError,setCameraError]=useState('')
 const [adminToken,setAdminToken]=useState(''),[adminStats,setAdminStats]=useState<Record<string,unknown>|null>(null),[adminBusy,setAdminBusy]=useState(false),[csvFile,setCsvFile]=useState<File|null>(null),[importResult,setImportResult]=useState<Record<string,unknown>|null>(null),[csvText,setCsvText]=useState('')
 const videoRef=useRef<HTMLVideoElement>(null),streamRef=useRef<MediaStream|null>(null),scanLock=useRef(false),dialogRef=useRef<HTMLDivElement>(null)
 const profileWrite=useRef<Promise<unknown>>(Promise.resolve()),profileVersion=useRef(0),savedProfile=useRef('')
 const t=(key:string)=>dictionary[key]?.[lang==='ru'?1:0]||key
 const notify=useCallback((msg:string)=>setToast(msg),[])
 const failure=useCallback((e:unknown)=>notify(e instanceof Error?e.message:'Xatolik yuz berdi'),[notify])
 const navigate=(next:Page)=>{setPage(next);setFilters(false);window.scrollTo({top:0,behavior:'smooth'})}
 const favoriteIds=new Set(favorites.map(p=>p.id))
 const cartCount=cart.reduce((s,x)=>s+x.quantity,0)
 const quoteKnown=(o:Offer)=>typeof o.total_price==='number'&&(o.is_demo||region==='tashkent')
 const scanPrices=scanResult?.offers.filter(o=>o.in_stock&&!o.stale&&quoteKnown(o)).map(o=>o.total_price as number)||[]
 const scanBest=scanPrices.length?Math.min(...scanPrices):null
 useEffect(()=>{window.Telegram?.WebApp.ready();window.Telegram?.WebApp.expand(); document.documentElement.lang=lang},[lang])
 useEffect(()=>{document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('ea-dark',String(dark))},[dark])
 useEffect(()=>{localStorage.setItem('ea-lang',lang)},[lang])
 useEffect(()=>{localStorage.setItem('ea-region',region);setBasket(null)},[region])
 useEffect(()=>{localStorage.setItem('ea-cart',JSON.stringify(cart));setBasket(null)},[cart])
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),4800);return()=>clearTimeout(timer)},[toast])
 useEffect(()=>{const timer=setTimeout(()=>{setDebounced(query);setListPage(1)},280);return()=>clearTimeout(timer)},[query])
 useEffect(()=>{Promise.all([api<Category[]>('/categories'),api<Store[]>('/stores'),api<Product[]>('/favorites'),api<Alert[]>('/alerts'),api<Profile>('/profile'),api<{demo_mode:boolean}>('/health')]).then(([c,s,f,a,p,h])=>{setCategories(c);setStores(s);setFavorites(f);setAlerts(a);savedProfile.current=JSON.stringify({region:p.region,language:p.language,notifications_enabled:p.notifications_enabled});setRegion(p.region);setLang(p.language);setNotifications(p.notifications_enabled);setRegions(p.regions.map(r=>[r.id,r.name]));setDemoMode(h.demo_mode);setProfileReady(true)}).catch(failure)},[failure])
 useEffect(()=>{if(!profileReady)return;const body=JSON.stringify({region,language:lang,notifications_enabled:notifications});if(body===savedProfile.current)return;const version=++profileVersion.current;setSettingsSaving(true);const save=profileWrite.current.catch(()=>undefined).then(()=>api<Profile>('/profile',{method:'PATCH',body}));profileWrite.current=save;void save.then(()=>{savedProfile.current=body}).catch(failure).finally(()=>{if(version===profileVersion.current)setSettingsSaving(false)})},[region,lang,notifications,profileReady,failure])
 useEffect(()=>{let current=true;setLoading(true);setError(''); const params=new URLSearchParams({q:debounced,category,sort,page:String(listPage),page_size:'12'});if(minPrice)params.set('min_price',minPrice);if(maxPrice)params.set('max_price',maxPrice);if(store)params.set('store',store);api<{items:Product[];total:number}>(`/products?${params}`).then(data=>{if(current){setProducts(data.items);setTotal(data.total)}}).catch(e=>{if(current)setError(e.message)}).finally(()=>{if(current)setLoading(false)});return()=>{current=false}},[debounced,category,sort,minPrice,maxPrice,store,listPage,refresh])
 const openProduct=useCallback(async(id:number)=>{setDetailLoading(true);setTarget('');try{await profileWrite.current.catch(()=>undefined);setSelected(await api<Detail>(`/products/${id}`))}catch(e){failure(e)}finally{setDetailLoading(false)}},[failure])
 useEffect(()=>{const product=searchParams.get('product');if(product&&/^\d+$/.test(product))void openProduct(Number(product))},[])
 useEffect(()=>{if(!selected)return;const previous=document.activeElement as HTMLElement|null;dialogRef.current?.focus();const handler=(e:KeyboardEvent)=>{if(e.key==='Escape')setSelected(null);if(e.key==='Tab'&&dialogRef.current){const focusable=dialogRef.current.querySelectorAll<HTMLElement>('button,a,input,select,textarea,[tabindex="0"]');const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};document.addEventListener('keydown',handler);const oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',handler);document.body.style.overflow=oldOverflow;previous?.focus()}},[selected])
 const toggleFavorite=async(p:Product)=>{const saved=favoriteIds.has(p.id);try{await api(`/favorites/${p.id}`,{method:saved?'DELETE':'POST'});setFavorites(prev=>saved?prev.filter(x=>x.id!==p.id):[p,...prev]);notify(saved?'Sevimlilardan olib tashlandi':'Sevimlilarga qo‘shildi')}catch(e){failure(e)}}
 const addCart=(p:Product)=>{if(p.min_price===null){notify('Mahsulot uchun mavjud taklif yo‘q');return}if(!cart.some(x=>x.product.id===p.id)&&cart.length>=8){notify('Bir hisobda eng ko‘pi 8 xil mahsulot');return}setCart(prev=>{const found=prev.find(x=>x.product.id===p.id);if(found)return prev.map(x=>x.product.id===p.id?{...x,quantity:Math.min(20,x.quantity+1)}:x);return[...prev,{product:p,quantity:1}]});window.Telegram?.WebApp.HapticFeedback?.impactOccurred('light');notify('Savatchaga qo‘shildi')}
 const toggleCompare=(p:Product)=>{setCompared(prev=>{if(prev.some(x=>x.id===p.id))return prev.filter(x=>x.id!==p.id);if(prev.length>=4){notify('Eng ko‘pi 4 ta mahsulotni solishtiring');return prev}return[...prev,p]})}
 const saveAlert=async()=>{if(!selected)return;const amount=Number(target);if(!Number.isFinite(amount)||amount<=0){notify('Musbat maqsadli narx kiriting');return}setAlertBusy(true);try{await api('/alerts',{method:'POST',body:JSON.stringify({product_id:selected.id,target_price:amount})});setAlerts(await api<Alert[]>('/alerts'));notify('Kuzatuv saqlandi. Telegram bildirishnomalari bot ulangach ishlaydi.');setTarget('')}catch(e){failure(e)}finally{setAlertBusy(false)}}
 const deleteAlert=async(id:number)=>{try{await api(`/alerts/${id}`,{method:'DELETE'});setAlerts(prev=>prev.filter(a=>a.id!==id));notify('Kuzatuv o‘chirildi')}catch(e){failure(e)}}
 const deleteAccount=async()=>{setDeleting(true);try{await profileWrite.current.catch(()=>undefined);await api('/profile',{method:'DELETE'});['ea-cart','ea-region','ea-lang'].forEach(key=>localStorage.removeItem(key));window.location.reload()}catch(e){failure(e);setDeleting(false)}}
 const toggleAlert=async(a:Alert)=>{try{await api(`/alerts/${a.id}`,{method:'PATCH',body:JSON.stringify({enabled:!a.enabled})});setAlerts(prev=>prev.map(x=>x.id===a.id?{...x,enabled:!a.enabled}:x))}catch(e){failure(e)}}
 const optimize=async()=>{setBasketBusy(true);try{setBasket(await api<BasketResult>('/basket/optimize',{method:'POST',body:JSON.stringify({items:cart.map(x=>({product_id:x.product.id,quantity:x.quantity})),region})}))}catch(e){failure(e)}finally{setBasketBusy(false)}}
 const ask=async(text=message)=>{if(!text.trim())return;setMessage(text);setAssistantBusy(true);try{setAnswer(await api('/assistant',{method:'POST',body:JSON.stringify({message:text})}))}catch(e){failure(e)}finally{setAssistantBusy(false)}}
 const lookup=useCallback(async(code:string)=>{setScanBusy(true);setScanResult(null);try{await profileWrite.current.catch(()=>undefined);setScanResult(await api<Detail>(`/barcode/${encodeURIComponent(code.trim())}`));setBarcode(code);setCamera(false)}catch(e){failure(e)}finally{setScanBusy(false)}},[failure])
 useEffect(()=>{if(!camera){streamRef.current?.getTracks().forEach(x=>x.stop());streamRef.current=null;return}let cancelled=false,timer:ReturnType<typeof setTimeout>|undefined;setCameraError('');const run=async()=>{if(!window.isSecureContext){setCameraError('Kamera uchun HTTPS yoki localhost manzili kerak. Kodni qo‘lda kiriting.');return}if(!window.BarcodeDetector){setCameraError('Bu brauzer EAN skanerlashni qo‘llamaydi. Shtrix-kod ostidagi raqamlarni kiriting.');return}try{const Detector=window.BarcodeDetector;const supported=Detector.getSupportedFormats?await Detector.getSupportedFormats():['ean_13','ean_8','upc_a'];const formats=['ean_13','ean_8','upc_a'].filter(format=>supported.includes(format));if(!formats.length){setCameraError('Bu brauzer EAN / UPC skanerlashni qo‘llamaydi. Kodni qo‘lda kiriting.');return}const detector=new Detector({formats});const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});if(cancelled){stream.getTracks().forEach(x=>x.stop());return}streamRef.current=stream;if(videoRef.current){videoRef.current.srcObject=stream;await videoRef.current.play()}const detect=async()=>{if(cancelled)return;if(videoRef.current?.readyState===4&&!scanLock.current){try{const codes=await detector.detect(videoRef.current);if(codes[0]){scanLock.current=true;await lookup(codes[0].rawValue);scanLock.current=false;return}}catch{/* next camera frame */}}timer=setTimeout(detect,350)};void detect()}catch(e){setCameraError(e instanceof Error?`Kamera ochilmadi: ${e.message}`:'Kamera ochilmadi')}};void run();return()=>{cancelled=true;clearTimeout(timer);streamRef.current?.getTracks().forEach(x=>x.stop())}},[camera,lookup])
 useEffect(()=>{if(page!=='scan')setCamera(false)},[page])
 const loadAdmin=async()=>{setAdminBusy(true);try{setAdminStats(await api('/admin/stats',{headers:{Authorization:`Bearer ${adminToken}`}}))}catch(e){failure(e)}finally{setAdminBusy(false)}}
 const importCsv=async(commit=false)=>{if(!csvFile)return;setAdminBusy(true);try{const text=commit?csvText:await csvFile.text();setCsvText(text);setImportResult(await api('/admin/import',{method:'POST',headers:{Authorization:`Bearer ${adminToken}`},body:JSON.stringify({csv_text:text,commit})}));if(commit)setRefresh(x=>x+1)}catch(e){failure(e)}finally{setAdminBusy(false)}}

 function ProductCard({product:p}:{product:Product}){return <article className="product-card"><div className="product-visual"><button className="art-button" aria-label={`${p.name}: ${t('details')}`} onClick={()=>void openProduct(p.id)}><Artwork product={p}/></button>{p.is_demo&&<span className="demo-tag">DEMO</span>}{p.discount_percent>0&&<span className="discount-tag">−{p.discount_percent}%</span>}<button className={`icon-button favorite-button ${favoriteIds.has(p.id)?'active':''}`} aria-label={favoriteIds.has(p.id)?'Sevimlilardan o‘chirish':'Sevimlilarga qo‘shish'} onClick={()=>void toggleFavorite(p)}><Heart size={18} fill={favoriteIds.has(p.id)?'currentColor':'none'}/></button></div><div className="product-body"><div className="product-meta"><span>{p.brand}</span><span className="store-count"><span className="tiny-dot"/>{p.store_count} {t('shops')}</span></div><button className="product-title" onClick={()=>void openProduct(p.id)}>{p.name}</button><p className="product-attributes">{Object.entries(p.attributes).slice(0,2).map(([,v])=>String(v)).join(' · ')||p.category_name}</p><div className="product-price">{money(p.min_price)} <span>so‘m</span></div><div className="product-bottom"><span className="lowest"><TrendingDown size={13}/> {p.min_price===null?'Yangilangan taklif yo‘q':'Eng past taklif'}</span><button disabled={p.min_price===null} className="mini-cart" aria-label={`${p.name} ${t('add')}`} onClick={()=>addCart(p)}><Plus size={18}/></button></div></div></article>}
 function Empty({children,icon=<ShoppingBag size={30}/>}:{children:ReactNode;icon?:ReactNode}){return <div className="empty-state"><div className="empty-icon">{icon}</div><h3>{t('empty')}</h3><p>{children}</p><button className="button primary" onClick={()=>navigate('catalog')}>{t('catalog')} <ArrowRight size={16}/></button></div>}
 function ProductGrid({items}:{items:Product[]}){return <div className="product-grid">{items.map(p=><ProductCard key={p.id} product={p}/>)}</div>}
 function InfoBox({children}:{children:ReactNode}){return <div className="info-box"><Info size={17}/><span>{children}</span></div>}
 const navItems:[Page,ReactNode][]=[['catalog',<Home size={21}/>],['favorites',<Heart size={21}/>],['basket',<ShoppingCart size={21}/>],['alerts',<Bell size={21}/>],['profile',<UserRound size={21}/>]]

 return <div className="app-shell antialiased">
 <aside className="sidebar"><a className="brand" href="#" aria-label="Engarzon bosh sahifa" title="Engarzon bosh sahifa" onClick={e=>{e.preventDefault();navigate('catalog')}}><span className="brand-symbol"><ShoppingCart size={23}/><span/></span><span>eng<span className="brand-blue">arzon</span><small>AQLLI XARID YORDAMCHISI</small></span></a><div className="sidebar-label">ASOSIY MENYU</div><nav>{navItems.filter(([id])=>id!=='profile').map(([id,icon])=><button key={id} aria-label={t(id)} title={t(id)} aria-current={page===id?'page':undefined} className={`side-link ${page===id?'selected':''}`} onClick={()=>navigate(id)}>{icon}<span>{t(id)}</span>{id==='basket'&&cartCount>0&&<b>{cartCount}</b>}{id==='alerts'&&alerts.length>0&&<b>{alerts.length}</b>}</button>)}</nav><div className="sidebar-label second-label">AQLLI VOSITALAR</div><nav>{([['scan',<ScanLine size={21}/>],['assistant',<Sparkles size={21}/>],['compare',<GitCompareArrows size={21}/>],['history',<BarChart3 size={21}/>]] as [Page,ReactNode][]).map(([id,icon])=><button key={id} aria-label={t(id)} title={t(id)} aria-current={page===id?'page':undefined} className={`side-link ${page===id?'selected':''}`} onClick={()=>navigate(id)}>{icon}<span>{t(id)}</span>{id==='assistant'&&<span className="new-pill">NEW</span>}</button>)}</nav><div className="sidebar-bottom"><div className="save-card"><div className="save-card-icon"><ShieldCheck size={22}/></div><b>Xaridingizni aqlli qiling</b><p>Narxlarni taqqoslang.<br/>Ortiqcha xarajatni tejang.</p><button onClick={()=>navigate('basket')}>Savatchani hisoblash <ArrowUpRight size={15}/></button></div><button aria-label={t('profile')} title={t('profile')} aria-current={page==='profile'?'page':undefined} className={`side-link ${page==='profile'?'selected':''}`} onClick={()=>navigate('profile')}><UserRound size={21}/><span>{t('profile')}</span></button><div className="version"><span className="tiny-dot"/> MVP 1.0 · {demoMode?'Demo rejim':'Hamkor katalog'}</div></div></aside>
 <div className="main-shell"><header className="topbar"><button type="button" className="mobile-brand" aria-label="Engarzon bosh sahifa" onClick={()=>navigate('catalog')}><span className="brand-symbol"><ShoppingCart size={20}/></span><b>engarzon</b></button><div className="desktop-breadcrumb">Xush kelibsiz! <span>Qulay xarid shu yerdan boshlanadi.</span></div><div className="topbar-actions"><label className="region-picker"><MapPin size={16}/><select aria-label="Yetkazish hududi" value={region} onChange={e=>setRegion(e.target.value)}>{regions.map(([id,name])=><option key={id} value={id}>{name}</option>)}</select><ChevronDown size={13}/></label><button className="icon-button theme-toggle" aria-label={dark?'Yorug‘ mavzu':'Qorong‘i mavzu'} onClick={()=>setDark(x=>!x)}>{dark?<Sun size={19}/>:<Moon size={19}/>}</button><button className="profile-avatar" aria-label={t('profile')} onClick={()=>navigate('profile')}>EA</button></div></header>
 <main className="main-content"><div className="demo-notice"><span className="notice-pill">{demoMode?'DEMO':'KATALOG'}</span><p>{demoMode?'Namuna katalogi. Narxlar va grafiklar sinov uchun; do‘konlarning jonli ma’lumotlari ulanmagan.':'Ruxsatli katalog ma’lumotlari. Narxning manbasi va yangilanish vaqtini mahsulot ichida tekshiring.'}</p><Info size={16}/></div>
 {(page==='catalog'||page==='history')&&<>
 <div className="page-title-row"><div><div className="eyebrow">HAR BIR XARIDDA KO‘PROQ TEJANG</div><h1>{page==='history'?t('history'):'Yaxshi narxni topish oson.'}</h1><p>{page==='history'?'Mahsulotni tanlab, saqlangan narxlar tarixi va xarid tavsiyasini ko‘ring.':'Sevimli mahsulotingiz. Bir nechta do‘kon. Eng qulay taklif.'}</p></div><span className="catalog-stamp"><ShieldCheck size={16}/> Manbasi ochiq narxlar</span></div>
 <div className="search-row"><label className="search-box"><Search size={21}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={t('search')} aria-label={t('search')}/>{query&&<button className="icon-button" aria-label={t('clear')} onClick={()=>setQuery('')}><X size={17}/></button>}<kbd>⌕</kbd></label><button aria-label="Filtrlar" title="Filtrlar" aria-expanded={filters} className={`button filter-button ${filters?'is-active':''}`} onClick={()=>setFilters(x=>!x)}><SlidersHorizontal size={18}/><span>Filtrlar</span>{(minPrice||maxPrice||store)&&<span className="filter-dot"/>}</button><button className="scan-search button" onClick={()=>navigate('scan')} aria-label={t('scan')}><ScanLine size={21}/></button></div>
 {filters&&<div className="filter-panel"><label>Minimum narx<input inputMode="numeric" type="number" min="0" value={minPrice} onChange={e=>{setMinPrice(e.target.value);setListPage(1)}} placeholder="0 so‘m"/></label><label>Maksimum narx<input inputMode="numeric" type="number" min="0" value={maxPrice} onChange={e=>{setMaxPrice(e.target.value);setListPage(1)}} placeholder="Cheklanmagan"/></label><label>Do‘kon<select value={store} onChange={e=>{setStore(e.target.value);setListPage(1)}}><option value="">Barcha do‘konlar</option>{stores.map(s=><option value={s.id} key={s.id}>{s.name}{s.is_demo?(s.adapter_status==='public'?' · Yetkazish tasdiqlanmagan':' · Demo'):''}</option>)}</select></label><button className="text-button" onClick={()=>{setMinPrice('');setMaxPrice('');setStore('');setCategory('');setListPage(1)}}>{t('clear')}</button></div>}
 {!debounced&&!category&&page==='catalog'&&<section className="hero-grid"><div className="hero-main"><div className="hero-copy"><span className="hero-pill"><Sparkles size={13}/> XARID QILISHDAN OLDIN SOLISHTIRING</span><h2>Bir xil mahsulot.<br/><span>Yaxshiroq narx.</span></h2><p>Do‘konlardagi takliflarni bir joyda ko‘ring.<br/>Sizga mos xaridni o‘zingiz tanlang.</p><button className="hero-button" onClick={()=>{setSort('discount');document.getElementById('products-heading')?.scrollIntoView({behavior:'smooth'})}}>Takliflarni ko‘rish <ArrowRight size={17}/></button></div><div className="hero-product"><div className="hero-orbit one"/><div className="hero-orbit two"/><Artwork product={{name:'iPhone 16 Pro',emoji:'📱',category_name:'Elektronika'}} hero/><div className="floating-saving"><span><TrendingDown size={17}/></span><div><small>Narxlarni solishtiring</small><b>Oqilona tanlang</b></div><Check size={17}/></div></div><div className="hero-dots"><i/><i/><i/></div></div><button className="basket-promo" onClick={()=>navigate('basket')}><span className="promo-icon"><ShoppingBag size={25}/><span className="spark-dot">✦</span></span><span className="promo-label">ENG ARZON SAVATCHA</span><h3>Ro‘yxat sizdan,<br/>hisob-kitob bizdan.</h3><p>Bir nechta mahsulotni yetkazish bilan eng arzon kombinatsiyada oling.</p><span className="promo-action">Savatcha tuzish <ArrowRight size={17}/></span><div className="promo-line"/></button></section>}
 <section className="categories"><div className="section-head"><h2><LayoutGrid size={18}/> Kategoriyalar</h2>{category&&<button className="text-button" onClick={()=>{setCategory('');setListPage(1)}}>Barchasi <ArrowRight size={14}/></button>}</div><div className="category-row"><button className={`category-card ${!category?'chosen':''}`} onClick={()=>{setCategory('');setListPage(1)}}><span className="category-emoji all-category"><LayoutGrid size={23}/></span><span>{t('all')}</span></button>{categories.filter(c=>!c.parent_id).map(c=><button key={c.id} className={`category-card ${category===c.slug?'chosen':''}`} onClick={()=>{setCategory(c.slug);setListPage(1)}}><span className="category-emoji">{c.emoji}</span><span>{c.name}</span></button>)}</div></section>
 <section className="products-section"><div className="section-head product-section-head"><div><h2 id="products-heading">{debounced?`“${debounced}” bo‘yicha natijalar`:category?categories.find(c=>c.slug===category)?.name:t('popular')} {!loading&&<span className="count-pill">{total}</span>}</h2><p>Yetkazish xarajati va narx tarixini mahsulot ichida ko‘ring</p></div><label className="sort-select"><span>Saralash:</span><select value={sort} aria-label="Saralash" onChange={e=>{setSort(e.target.value);setListPage(1)}}><option value="price_asc">{t('cheap')}</option><option value="price_desc">{t('expensive')}</option><option value="discount">{t('discount')}</option><option value="newest">{t('newest')}</option></select><ChevronDown size={14}/></label></div>{error?<div className="error-state"><AlertCircle/><p>{error}</p><button className="button primary" onClick={()=>setRefresh(x=>x+1)}><RefreshCw size={16}/>{t('retry')}</button></div>:loading?<div className="product-grid" aria-label={t('loading')}>{Array.from({length:8},(_,i)=><div className="skeleton-card" key={i}><div/><span/><span/><b/></div>)}</div>:products.length?<ProductGrid items={products}/>:<Empty icon={<Search size={30}/>}>Boshqa so‘z yozing yoki filtrlarni kamaytiring.</Empty>}{total>12&&!loading&&<div className="pagination"><button className="button" disabled={listPage===1} onClick={()=>setListPage(x=>x-1)}>Oldingi</button><span>{listPage} / {Math.ceil(total/12)}</span><button className="button" disabled={listPage>=Math.ceil(total/12)} onClick={()=>setListPage(x=>x+1)}>Keyingi <ChevronRight size={16}/></button></div>}</section>
 <div className="trust-strip"><div><ShieldCheck size={22}/><span><b>Manbasi ko‘rsatilgan</b><small>Demo va jonli narxlar ajratiladi</small></span></div><div><Bell size={22}/><span><b>Narxni kuzating</b><small>Maqsadli narxni o‘zingiz belgilang</small></span></div><div><ShoppingCart size={22}/><span><b>Yakuniy xarajat</b><small>Yetkazish ham hisobga olinadi</small></span></div></div>
 </>}

 {page==='favorites'&&<><PageHeading title={t('favorites')} subtitle="Yoqtirgan mahsulotlaringiz bir joyda. Narxlarni solishtirishni davom ettiring." icon={<Heart/>}/>{favorites.length?<ProductGrid items={favorites}/>:<Empty icon={<Heart size={30}/>}>Mahsulotdagi yurak belgisini bosing va uni shu yerda saqlang.</Empty>}</>}

 {page==='basket'&&<><PageHeading title="Eng arzon savatcha" subtitle="Mahsulotlar va har bir do‘konning yetkazish haqini birgalikda hisoblaymiz." icon={<ShoppingCart/>}/><InfoBox>Hisoblash {cart.some(x=>x.product.is_demo)?'demo':'katalogdagi yangilangan'} takliflar asosida amalga oshiriladi. Bir do‘konning yetkazish haqi bir marta qo‘shiladi. Hudud bo‘yicha haq ma’lum bo‘lmasa, natija bu haqda ogohlantiradi.</InfoBox>{!cart.length?<Empty>Kamida bitta mahsulotni savatchaga qo‘shing. Masalan, 5 ta mahsulot uchun eng arzon do‘konlar kombinatsiyasini topamiz.</Empty>:<div className="basket-layout"><div className="panel cart-panel"><div className="panel-title"><h3>Xarid ro‘yxati <span>{cart.length} xil mahsulot</span></h3><button className="text-button danger" onClick={()=>setCart([])}>{t('clear')}</button></div>{cart.map(({product:p,quantity})=><div className="cart-row" key={p.id}><button aria-label={`${p.name}: ${t('details')}`} className="cart-art" onClick={()=>void openProduct(p.id)}><Artwork product={p}/></button><div className="cart-description"><button onClick={()=>void openProduct(p.id)}>{p.name}</button><small>{money(p.min_price)} so‘mdan{p.is_demo?' · Demo':' · Katalog'}</small><b>{money((p.min_price||0)*quantity)} so‘m</b></div><div className="quantity-stepper"><button aria-label="Kamaytirish" disabled={quantity<=1} onClick={()=>setCart(prev=>prev.map(x=>x.product.id===p.id?{...x,quantity:quantity-1}:x))}><Minus size={14}/></button><span>{quantity}</span><button aria-label="Ko‘paytirish" disabled={quantity>=20} onClick={()=>setCart(prev=>prev.map(x=>x.product.id===p.id?{...x,quantity:quantity+1}:x))}><Plus size={14}/></button></div><button className="icon-button danger" aria-label={`${p.name} o‘chirish`} onClick={()=>setCart(prev=>prev.filter(x=>x.product.id!==p.id))}><Trash2 size={17}/></button></div>)}<button className="button add-more" onClick={()=>navigate('catalog')}><Plus size={17}/> Yana mahsulot qo‘shish</button></div><div className="panel basket-summary"><span className="eyebrow">AQLLI HISOB-KITOB</span><h3>Qancha tejash mumkin?</h3><p>Yetkazishni qo‘shgan holda eng arzon mavjud takliflar kombinatsiyasini topamiz.</p><label className="field-label">Yetkazish hududi<select value={region} onChange={e=>setRegion(e.target.value)}>{regions.map(([id,name])=><option key={id} value={id}>{name}</option>)}</select></label><button className="button primary full-width" disabled={basketBusy} onClick={()=>void optimize()}>{basketBusy?<LoaderCircle className="spinning" size={18}/>:<Sparkles size={18}/>} Hisoblash</button><small className="muted">Maksimum 8 xil mahsulot · {cart.some(x=>x.product.is_demo)?'Demo hisob':'Katalog hisobi'}</small></div>{basket&&<div className="basket-result panel"><div className="result-heading"><div><span className="eyebrow">ENG ARZON KOMBINATSIYA · {basket.is_demo?'DEMO':'KATALOG'}</span><h3>{money(basket.total)} <small>so‘m</small></h3></div>{basket.savings>0&&<span className="savings-badge"><TrendingDown size={17}/>{money(basket.savings)} so‘m tejaladi</span>}</div>{basket.stores.map(s=><div className="store-allocation" key={s.store_id}><div className="allocation-head"><span className="store-initial">{s.store_name[0]}</span><b>{s.store_name}</b><span>{money(s.total)} so‘m</span></div>{basket.items.filter(i=>i.store_id===s.store_id).map(i=><div className="allocation-item" key={i.product_id}><span>{i.name} × {i.quantity}</span><b>{money(i.subtotal)} so‘m</b></div>)}<div className="allocation-item delivery-line"><span>{t('delivery')}</span><span>{s.delivery_fee===0?'Bepul':`${money(s.delivery_fee)} so‘m`}</span></div></div>)}<div className="totals-row"><span>Mahsulotlar</span><b>{money(basket.subtotal)} so‘m</b></div><div className="totals-row"><span>Jami yetkazish</span><b>{money(basket.delivery_total)} so‘m</b></div><div className="totals-row final"><span>Yakuniy summa</span><b>{money(basket.total)} so‘m</b></div>{basket.single_store_total!==null&&<p className="muted">Barchasini bitta do‘kondan olish: {money(basket.single_store_total)} so‘m.</p>}{basket.warnings?.map((w,i)=><InfoBox key={i}>{w}</InfoBox>)}</div>}</div>}</>}

 {page==='alerts'&&<><PageHeading title="Narx kuzatuvlari" subtitle="Narx siz belgilagan qiymatga tushganda xabar olish uchun kuzatuv yarating." icon={<Bell/>}/><InfoBox>Kuzatuvlar bazada saqlanadi. Telegram xabarlari bot tokeni va ishchi jarayon sozlangandan keyin yuboriladi. Demo narxlari real do‘kon chegirmasi emas.</InfoBox>{alerts.length?<div className="alerts-list">{alerts.map(a=><div className="panel alert-row" key={a.id}><span className="alert-icon"><Bell size={22}/></span><div><button className="inline-title" onClick={()=>void openProduct(a.product_id)}>{a.product_name}</button><p>Maqsadli narx: <b>{money(a.target_price)} so‘m</b></p><small className="status-tag">{a.enabled?'Faol kuzatuv':'O‘chirilgan'}</small></div><button className={`toggle ${a.enabled?'on':''}`} role="switch" aria-checked={a.enabled} aria-label={`${a.product_name} kuzatuvini ${a.enabled?'o‘chirish':'yoqish'}`} onClick={()=>void toggleAlert(a)}><span/></button><button className="icon-button danger" aria-label="Kuzatuvni o‘chirish" onClick={()=>void deleteAlert(a.id)}><Trash2 size={18}/></button></div>)}</div>:<Empty icon={<Bell size={30}/>}>Mahsulotni oching va “Narx tushsa xabar bering” bo‘limida maqsadli narx kiriting.</Empty>}</>}

 {page==='scan'&&<><PageHeading title="Do‘konda skanerlab tekshiring" subtitle="Shtrix-kodni kiriting yoki kameradan foydalaning. Internetdagi yakuniy narx bilan solishtiring." icon={<ScanLine/>}/><div className="scan-layout"><div className="panel scanner-panel"><div className="scanner-symbol"><ScanLine size={48}/><span/></div><h3>Yaxshiroq narx borligini tekshiring</h3><p>EAN-8, EAN-13 yoki UPC kod ostidagi raqamlarni kiriting.</p><form onSubmit={(e:FormEvent)=>{e.preventDefault();void lookup(barcode)}}><label className="field-label">Shtrix-kod<input inputMode="numeric" autoComplete="off" value={barcode} onChange={e=>setBarcode(e.target.value.replace(/\s/g,''))} placeholder="Mahsulotdagi EAN / GTIN raqami" required minLength={8} maxLength={14}/></label><label className="field-label">Do‘kondagi narx, so‘m <span>(ixtiyoriy)</span><input type="number" min="1" inputMode="numeric" value={localPrice} onChange={e=>setLocalPrice(e.target.value)} placeholder="Do‘kondagi narxni yozing"/></label><button className="button primary full-width" disabled={scanBusy||!barcode.trim()}>{scanBusy?<LoaderCircle size={17} className="spinning"/>:<Search size={17}/>} Narxni tekshirish</button></form><button className="button full-width camera-button" onClick={()=>setCamera(x=>!x)}><Camera size={18}/>{camera?'Kamerani yopish':'Kamera bilan skanerlash'}</button>{camera&&<div className="camera-preview"><video ref={videoRef} playsInline muted autoPlay/>{cameraError&&<InfoBox>{cameraError}</InfoBox>}</div>}<small className="muted">Namuna kodini mahsulot tafsilotlaridan nusxalab sinashingiz mumkin. Katalogda topilmagan kod uchun narx to‘qilmaydi.</small></div><div>{scanResult?<div className="panel scan-match"><span className="status-tag"><Check size={13}/> Katalogda topildi{scanResult.is_demo?' · Demo':' · Katalog'}</span><Artwork product={scanResult}/><h3>{scanResult.name}</h3><p>Eng arzon mavjud yakuniy taklif</p><div className="big-price">{money(scanBest)} <small>so‘m</small></div><small className="muted">{scanBest===null?'Bu hudud uchun yangilangan yakuniy taklif yo‘q.':'Mahsulot + ma’lum yetkazish haqi · '+(regions.find(r=>r[0]===region)?.[1]||region)}</small>{scanResult.shipping_notice&&<InfoBox>{scanResult.shipping_notice}</InfoBox>}{Number(localPrice)>0&&scanBest!==null&&(()=>{const best=scanBest;const diff=Number(localPrice)-best;return <div className={`price-comparison ${diff>=0?'positive':'negative'}`}><TrendingDown size={20}/><div><b>{diff>0?`Internetda ${money(diff)} so‘m arzonroq`:diff<0?`Do‘konda ${money(-diff)} so‘m arzonroq`:'Narxlar teng'}</b><small>Taqqoslash {scanResult.is_demo?'demo':'katalog'} narxi bo‘yicha; sotuvchida tasdiqlang.</small></div></div>})()}<button className="button primary full-width" onClick={()=>void openProduct(scanResult.id)}>Barcha takliflarni ko‘rish <ArrowRight size={16}/></button></div>:<div className="scan-explainer"><div className="scan-step"><span>01</span><div><b>Mahsulotni toping</b><p>Shtrix-kodni kamera yoki qo‘lda kiriting.</p></div></div><div className="scan-step"><span>02</span><div><b>Variantni tekshiring</b><p>Model, hajm va rang aynan mosligiga qarang.</p></div></div><div className="scan-step"><span>03</span><div><b>Yakuniy narxni solishtiring</b><p>Yetkazish haqini ham hisobga oling.</p></div></div><InfoBox>Kamera ishlashi brauzerning BarcodeDetector imkoniyatiga bog‘liq. Qo‘lda kod kiritish har doim mavjud.</InfoBox></div>}</div></div></>}

 {page==='assistant'&&<><PageHeading title="Olish kerakmi yoki kutish?" subtitle="Saqlangan narxlar va katalog asosida tushunarli xarid maslahati." icon={<Sparkles/>}/><div className="assistant-layout"><div className="panel assistant-panel"><span className="assistant-orb"><Sparkles size={29}/></span><h2>Xaridni birga o‘ylab ko‘ramiz.</h2><p>Mahsulot nomi yoki byudjetingizni yozing. Katalogdagi mavjud takliflarni topamiz va narx tarixini tahlil qilamiz.</p><div className="mode-label"><span className="tiny-dot"/> Statistik maslahatchi · LLM ulanmagan</div><div className="prompt-examples">{['3 million so‘mgacha telefon','Samsung narxi hozir qulaymi?','Eng arzon noutbuk'].map(text=><button key={text} onClick={()=>void ask(text)}>{text}<ArrowUpRight size={15}/></button>)}</div><form className="assistant-input" onSubmit={e=>{e.preventDefault();void ask()}}><input value={message} onChange={e=>setMessage(e.target.value)} placeholder="Masalan: 5 million so‘mgacha noutbuk" aria-label="Maslahatchiga so‘rov" maxLength={1000}/><button aria-label="Yuborish" disabled={assistantBusy||!message.trim()}>{assistantBusy?<LoaderCircle size={19} className="spinning"/>:<Send size={19}/>}</button></form></div><div className="panel advice-principles"><h3>Tavsiya qanday ishlaydi?</h3><div><TrendingDown size={21}/><p><b>Narx tarixi</b><span>Joriy narx oldingi kuzatuvlar bilan taqqoslanadi.</span></p></div><div><BarChart3 size={21}/><p><b>Yetarli ma’lumot</b><span>Tarix yetarli bo‘lmasa, xulosa berilmaydi.</span></p></div><div><ShieldCheck size={21}/><p><b>Ochiq tushuntirish</b><span>Bu kelajak narxiga kafolat yoki narx prognozi emas.</span></p></div></div>{answer&&<div className="assistant-answer"><div className="panel answer-text"><span><Sparkles size={18}/> Statistik javob · {demoMode?'Demo katalog':'Katalog'}</span><p>{answer.answer}</p></div>{answer.products?.length>0&&<ProductGrid items={answer.products}/>}</div>}</div></>}

 {page==='compare'&&<><PageHeading title="Mahsulotlarni solishtiring" subtitle="Eng ko‘pi 4 ta mahsulotning aniq variantlari va narxlarini yonma-yon ko‘ring." icon={<GitCompareArrows/>}/>{compared.length?<div className="comparison-grid">{compared.map(p=><div className="panel comparison-card" key={p.id}><button className="icon-button comparison-remove" aria-label="Solishtirishdan o‘chirish" onClick={()=>toggleCompare(p)}><X size={18}/></button><Artwork product={p}/><h3>{p.name}</h3><div className="big-price">{money(p.min_price)}<small> so‘m</small></div><p>{p.store_count} do‘kon{p.is_demo?' · Demo':' · Katalog'}</p><dl><dt>Brend</dt><dd>{p.brand}</dd><dt>Model</dt><dd>{p.model}</dd>{Object.entries(p.attributes).map(([k,v])=><div key={k}><dt>{k}</dt><dd>{String(v)}</dd></div>)}</dl><button className="button primary full-width" onClick={()=>void openProduct(p.id)}>Takliflarni ko‘rish</button></div>)}</div>:<Empty icon={<GitCompareArrows size={30}/>}>Mahsulot tafsilotlarini oching va “Solishtirishga qo‘shish”ni bosing.</Empty>}</>}

 {page==='profile'&&<><PageHeading title={t('profile')} subtitle="Til, ko‘rinish va yetkazish hududini o‘zingizga moslang." icon={<UserRound/>}/><div className="profile-grid"><div className="panel profile-card"><span className="large-avatar">EA</span><h3>{window.Telegram?.WebApp.initData?'Telegram foydalanuvchisi':'Demo foydalanuvchi'}</h3><span className="mode-label">{window.Telegram?.WebApp.initData?'Telegram sessiyasi':'Mahalliy sinov sessiyasi'}</span><p>Haqiqiy profilingizni ulash uchun Mini App’ni sozlangan Telegram botidan oching.</p><div className="profile-stats"><div><b>{favorites.length}</b><span>Sevimli</span></div><div><b>{alerts.length}</b><span>Kuzatuv</span></div><div><b>{cart.length}</b><span>Savatchada</span></div></div></div><div className="panel settings-panel"><h3><Settings2 size={19}/> Shaxsiy sozlamalar</h3><div className="setting-row"><span><Globe size={19}/> Ilova tili</span><select aria-label="Ilova tili" value={lang} onChange={e=>setLang(e.target.value as Lang)}><option value="uz">O‘zbekcha</option><option value="ru">Русский</option></select></div><div className="setting-row"><span><Moon size={19}/> Qorong‘i mavzu</span><button className={`toggle ${dark?'on':''}`} role="switch" aria-checked={dark} aria-label="Qorong‘i mavzu" onClick={()=>setDark(x=>!x)}><span/></button></div><div className="setting-row"><span><Bell size={19}/> Bildirishnomalar</span><button className={`toggle ${notifications?'on':''}`} role="switch" aria-checked={notifications} aria-label="Telegram bildirishnomalari" disabled={!profileReady} onClick={()=>setNotifications(x=>!x)}><span/></button></div><div className="setting-row"><span><MapPin size={19}/> Hudud</span><select aria-label="Profil hududi" value={region} onChange={e=>setRegion(e.target.value)}>{regions.map(([id,name])=><option key={id} value={id}>{name}</option>)}</select></div><button className="setting-row settings-link" onClick={()=>navigate('admin')}><span><ShieldCheck size={19}/> Admin boshqaruvi</span><ChevronRight size={16}/></button><InfoBox>Premium, to‘lovlar va referral bonuslari bu MVPda ulanmagan. Obuna yoki bonus faollashgani haqida xabar berilmaydi.</InfoBox><p className="muted">{settingsSaving?'Sozlamalar saqlanmoqda…':'Til, hudud va bildirishnoma holati serverda saqlanadi. Ko‘rinish ushbu brauzerda saqlanadi.'} O‘zbekcha va ruscha asosiy navigatsiya mavjud; katalog ma’lumotlari manba tilida ko‘rsatiladi.</p><button className="text-button danger" onClick={()=>setConfirmDelete(x=>!x)}>Hisob ma’lumotlarini o‘chirish</button>{confirmDelete&&<div className="info-box"><div><p>Sevimlilar, kuzatuvlar va qidiruv tarixingiz o‘chiriladi. Qayta kirishda yangi bo‘sh hisob yaratiladi.</p><button className="button danger" disabled={deleting} onClick={()=>void deleteAccount()}>{deleting?'O‘chirilmoqda…':'Ha, ma’lumotlarimni o‘chirish'}</button><button className="button" disabled={deleting} onClick={()=>setConfirmDelete(false)}>Bekor qilish</button></div></div>}</div></div><div className="panel connections-panel"><h3>Do‘kon ulanishlari</h3><p className="muted">Hamkorlik katalogi yoki ruxsatli API ulangach jonli takliflar ishlaydi.</p>{stores.map(s=><div className="connection-row" key={s.id}><span className="store-initial">{s.name[0]}</span><b>{s.name}</b><span className="disconnected">{s.adapter_status==='public'?'Ochiq katalog':s.adapter_status==='csv'?'CSV katalog':s.adapter_status==='partner'?'Hamkor katalog':'Ulanmagan'}{s.is_demo?(s.adapter_status==='public'?' · Yetkazish tasdiqlanmagan':' · Demo'):''}</span></div>)}</div></>}

 {page==='admin'&&<><PageHeading title="Admin boshqaruvi" subtitle="Serverdagi ADMIN_TOKEN orqali himoyalangan. Token faqat joriy sahifa xotirasida saqlanadi." icon={<ShieldCheck/>}/><div className="panel admin-panel"><label className="field-label">Admin token<input type="password" autoComplete="off" value={adminToken} onChange={e=>setAdminToken(e.target.value)} placeholder="ADMIN_TOKEN"/></label><button className="button primary" disabled={!adminToken||adminBusy} onClick={()=>void loadAdmin()}>{adminBusy?<LoaderCircle size={17} className="spinning"/>:<BarChart3 size={17}/>} Statistikani ochish</button>{adminStats&&<div className="admin-results"><h3>Server statistikasi</h3><div className="stats-grid">{Object.entries(adminStats).filter(([,v])=>typeof v==='number'||typeof v==='string').map(([k,v])=><div key={k}><span>{k}</span><b>{String(v)}</b></div>)}</div><h3>CSV katalog importi</h3><p className="muted">CSV fayl formatini README va namunaviy katalog faylidan oling. Faqat ruxsatli manba ma’lumotini yuklang.</p><input type="file" accept=".csv,text/csv" onChange={e=>{setCsvFile(e.target.files?.[0]||null);setImportResult(null);setCsvText('')}}/><button className="button primary" disabled={!csvFile||adminBusy} onClick={()=>void importCsv(false)}>CSVni tekshirish</button>{importResult?.ok===true&&importResult?.committed!==true&&<button className="button primary" disabled={adminBusy} onClick={()=>void importCsv(true)}>Tekshirilgan CSVni bazaga saqlash</button>}{importResult&&<pre>{JSON.stringify(importResult,null,2)}</pre>}</div>}</div></>}

 <footer className="page-footer"><span>© {new Date().getFullYear()} Eng Arzon</span><span>Aqlli xarid. Ochiq ma’lumot. <span className="footer-demo">{demoMode?'DEMO VERSIYA':'MVP 1.0'}</span></span></footer>
 </main></div>
 <nav className="bottom-nav">{navItems.map(([id,icon])=><button key={id} aria-label={t(id)} title={t(id)} aria-current={page===id?'page':undefined} className={page===id?'selected':''} onClick={()=>navigate(id)}><span>{icon}{id==='basket'&&cartCount>0&&<b>{cartCount}</b>}</span><small>{id==='profile'?(lang==='ru'?'Профиль':'Profil'):t(id)}</small></button>)}</nav>
 {toast&&<div className="toast" role="status"><Info size={18}/><span>{toast}</span><button aria-label={t('close')} onClick={()=>setToast('')}><X size={15}/></button></div>}
 {detailLoading&&<div className="detail-loading" aria-label={t('loading')}><LoaderCircle className="spinning" size={34}/></div>}
 {selected&&<div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget)setSelected(null)}}><div className="product-dialog" ref={dialogRef} role="dialog" aria-modal="true" aria-label={selected.name} tabIndex={-1}><div className="dialog-top"><span><ShoppingBag size={17}/> Mahsulot tafsilotlari {selected.is_demo&&<span className="demo-tag inline">DEMO</span>}</span><button className="icon-button" aria-label={t('close')} onClick={()=>setSelected(null)}><X size={22}/></button></div><div className="detail-intro"><div className="detail-image"><Artwork product={selected}/><span>Rasm — mahsulot turining illyustratsiyasi</span></div><div className="detail-info"><span className="eyebrow">{selected.brand} · {selected.category_name}</span><h2>{selected.name}</h2><p>{selected.description}</p><div className="detail-attributes">{Object.entries(selected.attributes).map(([k,v])=><span key={k}>{k}: <b>{String(v)}</b></span>)}</div><div className="detail-price-label">Mavjud eng arzon mahsulot narxi</div><div className="detail-price">{money(selected.min_price)} <small>so‘m</small></div><div className="detail-actions"><button className="button primary" onClick={()=>addCart(selected)}><ShoppingCart size={17}/>{t('add')}</button><button className={`button ${favoriteIds.has(selected.id)?'favorite-active':''}`} aria-label="Sevimlilar" onClick={()=>void toggleFavorite(selected)}><Heart size={18} fill={favoriteIds.has(selected.id)?'currentColor':'none'}/></button><button className="button" aria-label="Solishtirishga qo‘shish" onClick={()=>toggleCompare(selected)}>{compared.some(p=>p.id===selected.id)?<Check size={18}/>:<GitCompareArrows size={18}/>}</button></div>{selected.barcode&&<small className="barcode-label">Shtrix-kod: <button onClick={()=>{setBarcode(selected.barcode!);setSelected(null);navigate('scan')}}>{selected.barcode} <ScanLine size={13}/></button></small>}</div></div><section className="offers-section"><h3>Do‘konlar bo‘yicha takliflar <span className="count-pill">{selected.offers.length}</span></h3><p>Mahsulot narxi + ma’lum yetkazish haqi. Manba va yangilanish vaqtini tekshiring.</p>{selected.shipping_notice&&<InfoBox>{selected.shipping_notice}</InfoBox>}<div className="offers-table"><div className="offer-table-header"><span>Do‘kon</span><span>Narxi</span><span>Yetkazish</span><span>Yakuniy summa</span><span>Holat</span></div>{selected.offers.map((o,i)=><div className={`offer-row ${i===0&&o.in_stock&&!o.stale&&quoteKnown(o)?'best-offer':''}`} key={o.id}><div className="offer-store"><span className="store-initial">{o.store_name[0]}</span><div><b>{o.store_name}</b><small>{new Date(o.updated_at).toLocaleDateString('uz-UZ')}{o.is_demo?' · Demo':' · Katalog'}{i===0&&o.in_stock&&!o.stale&&quoteKnown(o)?' · Eng qulay':''}</small></div></div><span>{money(o.price)} <small>so‘m</small></span><span>{o.delivery_fee===null?'Aniqlanmagan':o.delivery_fee===0?'Bepul':`${money(o.delivery_fee)} so‘m`}</span><b>{money(o.total_price)} <small>so‘m</small></b><span className={o.in_stock&&!o.stale?'status-tag':'disconnected'}>{o.stale?'Eskirgan':o.in_stock?(o.is_demo?'Mavjud · Demo':'Mavjud'):'Mavjud emas'}</span>{o.url&&/^https:\/\//.test(o.url)&&<a href={o.url} target="_blank" rel="noopener noreferrer" className="offer-external">Do‘konda ochish <ExternalLink size={13}/></a>}</div>)}</div></section><section className="history-section"><div className="section-head"><h3><BarChart3 size={18}/> Narxlar tarixi</h3><span className="subtle-pill">Saqlangan kuzatuvlar{selected.history.some(h=>h.is_demo)?' · Demo':''}</span></div><PriceChart history={selected.history}/><div className={`insight-card ${selected.insight.verdict}`}><span className="insight-icon">{selected.insight.verdict==='buy'?<TrendingDown/>:selected.insight.verdict==='wait'?<ArrowDownRight/>:<Info/>}</span><div><span className="eyebrow">STATISTIK TAHLIL{selected.insight.is_demo?' · DEMO TARIX':' · KATALOG TARIXI'}</span><h4>{selected.insight.title}</h4><p>{selected.insight.explanation}</p><small>{selected.insight.sample_count} kuzatuv · {selected.insight.span_days} kun. Kelajak narxi kafolatlanmaydi.</small></div></div></section><section className="alert-create"><div><Bell size={22}/><div><h3>Narx tushsa xabar bering</h3><p>Maqsadli narxni belgilang. Kuzatuv bazada saqlanadi.</p></div></div><div className="alert-create-form"><input type="number" min="1" inputMode="numeric" value={target} onChange={e=>setTarget(e.target.value)} placeholder="Maqsadli narx, so‘m" aria-label="Maqsadli narx"/><button className="button primary" disabled={alertBusy||!target} onClick={()=>void saveAlert()}>{alertBusy?<LoaderCircle size={16} className="spinning"/>:<Bell size={16}/>} Kuzatish</button></div></section></div></div>}
 </div>
}

function PageHeading({title,subtitle,icon}:{title:string;subtitle:string;icon:ReactNode}){return <div className="feature-page-heading"><span>{icon}</span><div><h1>{title}</h1><p>{subtitle}</p></div></div>}
function PriceChart({history}:{history:Detail['history']}){
 const [period,setPeriod]=useState(30)
 const latest=Date.parse(new Date().toISOString().slice(0,10)+'T00:00:00Z')
 const filtered=history.filter(h=>new Date(h.date).getTime()>=latest-(period-1)*86400000&&new Date(h.date).getTime()<=latest).sort((a,b)=>new Date(a.date).getTime()-new Date(b.date).getTime())
 const prices=filtered.map(h=>h.price),min=Math.min(...prices),max=Math.max(...prices),range=Math.max(max-min,max*.02,1),pad=range*.2
 const start=filtered.length?new Date(filtered[0].date).getTime():latest
 const end=filtered.length?new Date(filtered[filtered.length-1].date).getTime():latest
 const x=(i:number)=>filtered.length<=1?450:60+(new Date(filtered[i].date).getTime()-start)/Math.max(end-start,1)*790
 const y=(p:number)=>190-(p-min+pad)/(range+2*pad)*150
 const points=filtered.map((h,i)=>`${x(i)},${y(h.price)}`).join(' ')
 return <><div className="chart-periods">{[7,30,90,180].map(d=><button key={d} className={period===d?'active':''} onClick={()=>setPeriod(d)}>{d} kun</button>)}</div>{filtered.length<2?<div className="no-history"><BarChart3 size={25}/><p>Bu davr uchun kamida ikkita kuzatuv kerak. Grafik uydirilmaydi.</p></div>:<div className="price-chart"><svg viewBox="0 0 900 240" role="img" aria-label={`So‘nggi ${period} kunlik saqlangan narx tarixi`}><defs><linearGradient id="priceArea" x1="0" y1="0" x2="0" y2="1"><stop stopColor="#1b61ee" stopOpacity=".2"/><stop offset="1" stopColor="#1b61ee" stopOpacity="0"/></linearGradient></defs>{[0,.5,1].map((ratio,i)=>{const price=min+range*ratio;return <g key={i}><line x1="60" y1={y(price)} x2="855" y2={y(price)} stroke="currentColor" opacity=".08" strokeDasharray="5 5"/><text x="0" y={y(price)+4} fill="currentColor" opacity=".5" fontSize="12">{price>=1000000?`${(price/1000000).toFixed(1)} mln`:money(price)}</text></g>})}<path d={`M ${x(0)},205 L ${points.replaceAll(' ',' L ')} L ${x(filtered.length-1)},205 Z`} fill="url(#priceArea)"/><polyline points={points} fill="none" stroke="#1b61ee" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/>{filtered.map((h,i)=><circle key={i} cx={x(i)} cy={y(h.price)} r="3" fill="#1b61ee"><title>{new Date(h.date).toLocaleDateString('uz-UZ')}: {money(h.price)} so‘m{h.is_demo?' · Demo':''}</title></circle>)}{[0,Math.floor((filtered.length-1)/2),filtered.length-1].filter((v,i,a)=>a.indexOf(v)===i).map(i=><text key={i} x={x(i)} y="233" fill="currentColor" opacity=".5" fontSize="12" textAnchor="middle">{new Date(filtered[i].date).toLocaleDateString('uz-UZ',{day:'numeric',month:'short'})}</text>)}</svg><p className="chart-note">Faqat saqlangan {filtered.length} ta kuzatuv ko‘rsatilgan. Yo‘q davrlar uchun narx yaratilmagan.</p></div>}</>
}
